USE [golden_db];
SET XACT_ABORT ON;
SET LOCK_TIMEOUT 30000;
BEGIN TRANSACTION;
DROP INDEX [UX_products_sku] ON [sales].[products];
ALTER TABLE [sales].[products] ALTER COLUMN [sku] char(12) COLLATE Latin1_General_100_CS_AS NOT NULL;
ALTER TABLE [sales].[products] ALTER COLUMN [label] nvarchar(max) COLLATE Latin1_General_100_CS_AS NULL;
CREATE UNIQUE NONCLUSTERED INDEX [UX_products_sku] ON [sales].[products] ([sku] ASC, [created] DESC) INCLUDE ([label], [price]) WHERE ([sku] IS NOT NULL) WITH (PAD_INDEX = ON, FILLFACTOR = 80, IGNORE_DUP_KEY = ON, STATISTICS_NORECOMPUTE = ON, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = OFF, DATA_COMPRESSION = PAGE) ON [INDEXES];
COMMIT TRANSACTION;
